  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel ContactMessage {\n  id        String   @id @default(cuid())\n  name      String\n  email     String\n  message   String\n  createdAt DateTime @default(now())\n}\n\nmodel InviteResponse {\n  id         String   @id @default(cuid())\n  senderName String\n  friendName String\n  plan       String\n  ipHash     String?\n  acceptedAt DateTime @default(now())\n}\n\nmodel Subscriber {\n  id            String          @id @default(cuid())\n  name          String?\n  email         String          @unique\n  status        String          @default(\"active\") // \"active\" | \"unsubscribed\"\n  createdAt     DateTime        @default(now())\n  EmailDelivery EmailDelivery[]\n}\n\n// ==========================================\n// PORTFOLIO CMS CONTENT\n// ==========================================\n\nmodel Experience {\n  id          String   @id @default(cuid())\n  company     String\n  role        String\n  startDate   String\n  endDate     String\n  description String   @db.Text\n  order       Int      @default(0)\n  createdAt   DateTime @default(now())\n}\n\nmodel Education {\n  id          String   @id @default(cuid())\n  school      String\n  degree      String\n  startDate   String\n  endDate     String\n  description String?  @db.Text\n  order       Int      @default(0)\n  createdAt   DateTime @default(now())\n}\n\nmodel Project {\n  id          String   @id @default(cuid())\n  title       String\n  category    String\n  description String   @db.Text\n  tags        String[] // PostgreSQL supports string arrays natively\n  link        String?\n  github      String?\n  featured    Boolean  @default(false)\n  order       Int      @default(0)\n  createdAt   DateTime @default(now())\n}\n\nmodel Certificate {\n  id        String   @id @default(cuid())\n  name      String\n  issuer    String\n  date      String\n  url       String?\n  order     Int      @default(0)\n  createdAt DateTime @default(now())\n}\n\nmodel Skill {\n  id        String   @id @default(cuid())\n  category  String\n  name      String\n  order     Int      @default(0)\n  createdAt DateTime @default(now())\n\n  @@index([category, order])\n}\n\nmodel EmailTemplate {\n  id            String          @id @default(cuid())\n  name          String // e.g. \"IBM Hackathon Announcement\"\n  subject       String\n  html          String          @db.Text\n  createdAt     DateTime        @default(now())\n  updatedAt     DateTime        @updatedAt\n  EmailCampaign EmailCampaign[]\n}\n\n// ==========================================\n// YES-ONLY INVITE — AI joke cache\n// ==========================================\n\nmodel Question {\n  id         String   @id @default(cuid())\n  normalized String   @unique\n  original   String\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  answers Answer[]\n}\n\nmodel Answer {\n  id         String   @id @default(cuid())\n  questionId String\n  question   Question @relation(fields: [questionId], references: [id], onDelete: Cascade)\n  content    String   @db.Text\n  usageCount Int      @default(0)\n  createdAt  DateTime @default(now())\n\n  @@index([questionId])\n}\n\nmodel SiteSettings {\n  id           String   @id @default(\"global\")\n  fullName     String   @default(\"Kidus Amanuel\")\n  headline     String   @default(\"Full-Stack & AI Engineer\")\n  phone        String   @default(\"+251 900 000 000\")\n  location     String   @default(\"Addis Ababa, Ethiopia (Open to Remote)\")\n  websiteUrl   String   @default(\"https://kidus-portfolio-gray.vercel.app\")\n  summary      String   @default(\"Full-stack engineer with 3+ years building scalable SaaS applications and production AI systems.\") @db.Text\n  contactEmail String   @default(\"kidusamanuel@yahoo.com\")\n  senderEmail  String   @default(\"kidusamanuel0371@gmail.com\")\n  githubUrl    String   @default(\"https://github.com/Kidus-Amanuel\")\n  linkedinUrl  String   @default(\"https://linkedin.com/in/kidus-amanuel\")\n  instagramUrl String   @default(\"\")\n  upworkUrl    String   @default(\"\")\n  updatedAt    DateTime @updatedAt\n}\n\nmodel EmailCampaign {\n  id              String        @id @default(cuid())\n  templateId      String\n  template        EmailTemplate @relation(fields: [templateId], references: [id])\n  status          String        @default(\"DRAFT\") // DRAFT, RUNNING, PAUSED, COMPLETED\n  batchSize       Int           @default(50)\n  intervalMinutes Int           @default(10)\n  nextRunAt       DateTime?\n  createdAt       DateTime      @default(now())\n  updatedAt       DateTime      @updatedAt\n\n  deliveries EmailDelivery[]\n}\n\nmodel EmailDelivery {\n  id           String        @id @default(cuid())\n  campaignId   String\n  campaign     EmailCampaign @relation(fields: [campaignId], references: [id], onDelete: Cascade)\n  subscriberId String\n  subscriber   Subscriber    @relation(fields: [subscriberId], references: [id], onDelete: Cascade)\n  templateId   String\n  status       String        @default(\"PENDING\") // PENDING, SENT, FAILED\n  error        String?       @db.Text\n  sentAt       DateTime?\n  createdAt    DateTime      @default(now())\n  updatedAt    DateTime      @updatedAt\n\n  @@unique([subscriberId, templateId])\n  @@index([campaignId, status])\n}\n\n// ==========================================\n// MEETING BOOKING SYSTEM\n// ==========================================\n\nmodel Booking {\n  id                String    @id @default(cuid())\n  requesterName     String\n  requesterEmail    String\n  requesterPhone    String?\n  requesterCompany  String?\n  requesterTimezone String    @default(\"Africa/Nairobi\")\n  topic             String\n  notes             String?   @db.Text\n  durationMinutes   Int       @default(30)\n  /// Instant the visitor proposed (never changes).\n  proposedAt        DateTime\n  /// Instant the meeting is actually booked for (may be moved by the host).\n  startsAt          DateTime\n  endsAt            DateTime\n  /// PENDING | ACCEPTED | DECLINED | CANCELLED\n  status            String    @default(\"PENDING\")\n  /// GOOGLE_MEET | ZOOM | WHATSAPP | TELEGRAM\n  platform          String    @default(\"GOOGLE_MEET\")\n  meetingUrl        String?\n  meetingId         String?\n  /// Host-only join URL (Zoom start_url).\n  hostUrl           String?\n  meetingPassword   String?\n  calendarEventId   String?\n  calendarHtmlLink  String?\n  /// Human-readable note about a partial failure (e.g. calendar auth missing).\n  failureReason     String?   @db.Text\n  decidedAt         DateTime?\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n\n  @@index([status, proposedAt])\n  @@index([requesterEmail])\n}\n\n// Key/value store for runtime-configurable integration credentials.\n// Environment variables always win over rows in this table.\nmodel AppSetting {\n  key       String   @id\n  value     String   @db.Text\n  updatedAt DateTime @updatedAt\n}\n",
